_CONTENT_TYPE = {
    "AI Image Generation": "Image",
    "AI Video": "Video",
    "Audio & Music": "Audio",
    "Coding & Development": "Code",
}
_TOOL = {
    "AI Image Generation": "Midjourney",
    "AI Video": "Sora",
}
_DIFF_CYCLE = ["Beginner", "Intermediate", "Advanced"]


def build_extra_prompts():
    """Expand EXTRA into full prompt docs (without id/timestamps)."""
    out = []
    for category, items in EXTRA.items():
        for i, item in enumerate(items):
            title = item[0]
            content = item[1]
            subcategory = item[2] if len(item) > 2 else None
            tool = None
            if category == "AI Tool-Specific":
                tool = subcategory  # tool name stored in 3rd slot
                subcategory = None
            else:
                tool = _TOOL.get(category)
            out.append({
                "title": title,
                "content": content,
                "category": category,
                "subcategory": subcategory,
                "tool": tool,
                "industry": subcategory if category == "Industry-Specific" else "General",
                "difficulty": _DIFF_CYCLE[i % 3],
                "use_case": None,
                "content_type": _CONTENT_TYPE.get(category, "Text"),
            })
    return out
